mapper.select:
SELECT
FROM BBS_ARTICLE B LEFT JOIN EDU_PRGRM_MST P ON P.PRGRM_TYPE_CD = B.ETC3 AND P.PRGRM_SN = CAST(NULLIF(B.ETC4, '') AS UNSIGNED) AND P.DEL_DT IS NULL
ORDER BY B.REG_DT DESC, B.PST_SN DESC LIMIT #{offset}, #{limit}

mapper.delete:
DELETE FROM BBS_ARTICLE
WHERE BBS_ID = 'LRNSUP'
AND PST_SN = #{pstSn}
